head.script:
scwin.onLoadComplete = function() {
    comLib.setCmnCd({
        WAMNRSCD: "sbx_condition_RSR",
        AASTDCD: "sbx_condition_CSR",
        DDAYCD: "grd_KNDAMN_BY_EQP_BY.DDAYCD,grd_CLBR_BY.DDAYCD,grd_SUBOR_BY.DDAYCD",
        AMNRQMOPRPSCD: "grd_KNDAMN_STEP_BY_ALLTMT_GNRZ.OPRPSCD"
    }, {
        isUseVal: true
    });
    dl_cmnCd_WAMNRSCD.setColumnFilter({
        type: 'row',
        colIndex: 'VAL2',
        key: "Y",
        condition: 'and'
    });
    dm_condition.set("APLY_YEAR", $w.getCurrentServerDate('yyyy'));
    dm_condition.set("UC", comLib.getSession().SELECTED_UC);
    dm_condition.set("MDCD", comLib.getSession().SELECTED_UC_UNIT_MDCD);
    //AA/CSR기준 셋팅
    sbx_condition_RSR.setValue(f02Lib.selectAACsrStd());
};
scwin.btn_select_onclick = function() {
    if (comLib.checkSelect()) {
        if (sbx_condition_YEAR.getValue().length < 1) {
            comLib.alert("작성년도를 입력하세요.");
            sbx_condition_YEAR.focus();
            return;
        }
        if (sbx_condition_RSR.getValue().length < 1) {
            comLib.alert("작성기준을 입력하세요.");
            sbx_condition_RSR.focus();
            return;
        }
        if (sbx_condition_CSR.getValue().length < 1) {
            comLib.alert("적용기준을 입력하세요.");
            sbx_condition_CSR.focus();
            return;
        }
        var tabId = tab.getSelectedTabID();
        if (tabId == "KNDAMN_BY_EQP_BY") { //탄종별/장비별  
            ajaxLib.executeSubmission("sbm_selectAACSRSytsKndamnByEqpBy", {
                logDvsCd: "04"
            });
        } else if (tabId == "CLBR_BY") { //구경별
            ajaxLib.executeSubmission("sbm_selectAACSRSytsClbrBy", {
                logDvsCd: "04"
            });
        } else if (tabId == "SUBOR_BY") { //예하부대별
            ajaxLib.executeSubmission("sbm_selectAACSRSytsSuborBy", {
                logDvsCd: "04"
            });
        } else if (tabId == "SUBOR_STEP_BY") { //예하/단계별 할당(톤) 
            ajaxLib.executeSubmission("sbm_selectAACSRSytsSuborStepBy", {
                logDvsCd: "04"
            });
        } else if (tabId == "STEP_BY_ALLTMT_GNRZ") { //단계별할당총괄현황
            ajaxLib.executeSubmission("sbm_selectAACSRSytsStepByAlltmtGnrz", {
                logDvsCd: "04"
            });
        } else if (tabId == "KNDAMN_BY_STEP_BY_ALLTMT_GNRZ") { //탄종별/단계별할당총괄	
            ajaxLib.executeSubmission("sbm_selectAACSRSytsKndamnByStepByAlltmtGnrz", {
                logDvsCd: "04"
            });
        } else if (tabId == "KNDAMN_STEP_BY_ALLTMT_GNRZ") { //탄종/단계별 할당총괄
            ajaxLib.executeSubmission("sbm_selectAACSRSytsKndamnStepByAllTmtGnrz", {
                logDvsCd: "04"
            });
        } else if (tabId == "KNDAMN_BY_WHLAM_CNTNC_DAY") { //탄종별전군지속일
            ajaxLib.executeSubmission("sbm_selectAACSRSytsKndamnByWhlamCntncDay", {
                logDvsCd: "04"
            });
        }
    }
};
scwin.sbm_selectAACSRSytsKndamnByEqpBy_successCallback = function(resJson) {
    grd_KNDAMN_BY_EQP_BY.setFocusedCell(0, 0);
    spn_cnt_KNDAMN_BY_EQP_BY.setLabel(dl_kndamnByEqpBy.getRowCount());
    dl_kndamnByEqpBy.reform();
};
scwin.sbm_selectAACSRSytsClbrBy_successCallback = function(resJson) {
    grd_CLBR_BY.setFocusedCell(0, 0);
    spn_cnt_CLBR_BY.setLabel(dl_clbrBy.getRowCount());
    dl_clbrBy.reform();
};
scwin.sbm_selectAACSRSytsSuborBy_successCallback = function(resJson) {
    grd_SUBOR_BY.setFocusedCell(0, 0);
    spn_cnt_SUBOR_BY.setLabel(dl_suborBy.getRowCount());
    dl_suborBy.reform();
};
scwin.sbm_selectAACSRSytsSuborStepBy_successCallback = function(resJson) {
    dl_suborStepBy.reform();
};
scwin.sbm_selectAACSRSytsStepByAlltmtGnrz_successCallback = function(resJson) {
    dl_stepByAlltmtGnrz.reform();
};
scwin.sbm_selectAACSRSytsKndamnByStepByAlltmtGnrz_successCallback = function(resJson) {
    dl_kndamnByStepByAlltmtGnrz.reform();
};
scwin.sbm_selectAACSRSytsKndamnStepByAllTmtGnrz_successCallback = function(resJson) {
    grd_KNDAMN_STEP_BY_ALLTMT_GNRZ.setFocusedCell(0, 0);
    spn_cnt_KNDAMN_STEP_BY_ALLTMT_GNRZ.setLabel(dl_kndamnStepByAlltmtGnrz.getRowCount());
    dl_kndamnStepByAlltmtGnrz.reform();
};
scwin.sbm_selectAACSRSytsKndamnByWhlamCntncDay_successCallback = function(resJson) {
    grd_KNDAMN_BY_WHLAM_CNTNC_DAY.setFocusedCell(0, 0);
    spn_cnt_KNDAMN_BY_WHLAM_CNTNC_DAY.setLabel(dl_kndamnByWhlamCntncDay.getRowCount());
    dl_kndamnByWhlamCntncDay.reform();
};
scwin.tab_onchange = function(tabID, idx, userTabID) {};
scwin.btn_downTab1_onclick = function() {
    comLib.excelDownload("grd_KNDAMN_BY_EQP_BY", "탄종별/장비별");
};
scwin.btn_downTab2_onclick = function() {
    comLib.excelDownload("grd_CLBR_BY", "구경별");
};
scwin.btn_downTab3_onclick = function() {
