scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'tab_tab_KNDAMN_BY_STEP_BY_ALLTMT_GNRZ').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'grd_KNDAMN_BY_STEP_BY_ALLTMT_GNRZ_container_scrollX').scrollLeft = 500");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'grd_KNDAMN_BY_STEP_BY_ALLTMT_GNRZ_container_scrollX').scrollLeft = 1000");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'grd_KNDAMN_BY_STEP_BY_ALLTMT_GNRZ_container_scrollX').scrollLeft = 1500");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq(WebSquare.wUnit.getDomById($p.id+'grd_KNDAMN_BY_STEP_BY_ALLTMT_GNRZ_body_table')).children().length == 3", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
